package com.bank.filing;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.logging.Logger;

// One topological pass answers BOTH: can-finish (I) and the order (II).
public class FilingScheduler {

    private static final Logger log = Logger.getLogger(FilingScheduler.class.getName());

    // Core pass used by both public methods.
    private List<Integer> topoOrder(int numFilings, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < numFilings; i++) adj.add(new ArrayList<>());
        int[] inDegree = new int[numFilings];
        for (int[] p : prerequisites) {
            adj.get(p[1]).add(p[0]);  // p[1] before p[0]
            inDegree[p[0]]++;
        }
        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < numFilings; i++) {
            if (inDegree[i] == 0) queue.add(i);
        }
        List<Integer> order = new ArrayList<>();
        while (!queue.isEmpty()) {
            int f = queue.poll();
            order.add(f);
            for (int next : adj.get(f)) {
                if (--inDegree[next] == 0) queue.add(next);
            }
        }
        return order; // size < numFilings ⇒ cycle
    }

    // Course Schedule I
    public boolean canComplete(int numFilings, int[][] prerequisites) {
        boolean ok = topoOrder(numFilings, prerequisites).size() == numFilings;
        log.info("canComplete=" + ok);
        return ok;
    }

    // Course Schedule II
    public int[] completionOrder(int numFilings, int[][] prerequisites) {
        List<Integer> order = topoOrder(numFilings, prerequisites);
        if (order.size() != numFilings) {
            log.info("Cycle detected; no completion order");
            return new int[0];
        }
        int[] result = order.stream().mapToInt(Integer::intValue).toArray();
        log.info("Completion order: " + order);
        return result;
    }
}
