package com.bank.filing;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class FilingDemo {

    private static final Logger log = Logger.getLogger(FilingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Regulatory Filing Scheduler (I + II)");
        FilingScheduler scheduler = new FilingScheduler();
        int[][] prereqs = {{1, 0}, {2, 0}, {3, 1}, {3, 2}};

        scheduler.canComplete(4, prereqs);      // true  (Schedule I)
        scheduler.completionOrder(4, prereqs);  // [0,1,2,3] (Schedule II)

        int[][] cyclic = {{1, 0}, {0, 1}};
        scheduler.canComplete(2, cyclic);       // false
        scheduler.completionOrder(2, cyclic);   // []
    }
}
